/* Twemoji в Chrome через Stylish — для всех сайтов */

/* 1) Даём браузеру локальный шрифт Twemoji и ограничиваемся эмодзи-диапазонами */
@font-face {
  font-family: "TwemojiOverride";
  src: local("Twemoji Mozilla"), local("Twemoji"), local("Twemoji Color"), local("Twitter Color Emoji");
  unicode-range:
    U+1F1E6-1F1FF, /* Флаги */
    U+1F300-1F5FF, /* Разные пиктограммы */
    U+1F600-1F64F, /* Смайлы */
    U+1F680-1F6FF, /* Транспорт и карта */
    U+1F700-1F77F, /* Алхимические */
    U+1F780-1F7FF, /* Геометрические доп. */
    U+1F800-1F8FF, /* Доп. стрелки */
    U+1F900-1F9FF, /* Доп. символы и пиктограммы */
    U+1FA70-1FAFF, /* Extended-A */
    U+2600-26FF,   /* Разные символы */
    U+2700-27BF,   /* Дингбаты */
    U+1F3FB-1F3FF, /* Скин-тоны */
    U+200D,        /* ZWJ */
    U+FE0F,        /* Variation Selector-16 */
    U+20E3;        /* Обводка для клавиш */
}

/* 2) Ставим Twemoji первым, обычные буквы берутся из системных шрифтов */
html, body, input, textarea, button, select, div, span, p, a, li,
h1, h2, h3, h4, h5, h6 {
  font-family: "TwemojiOverride", system-ui, -apple-system, "Segoe UI",
               Roboto, "Helvetica Neue", Arial, sans-serif !important;
}
